    public void setCustomName(net.minecraft.network.chat.Component name){var builder=net.minecraft.core.component.DataComponentMap.builder().addAll(collectComponents());if(name!=null)builder.set(DataComponents.CUSTOM_NAME,name);else builder.set(DataComponents.CUSTOM_NAME,null);applyImplicitComponents(builder.build());setChanged();}
    public boolean portable(){return block().function.equals("statue")|| block().function.equals("globe")||block().function.equals("flag")||block().function.equals("goblet")||block().function.equals("spikes")||block().function.equals("blackboard")||block().function.equals("jar")||block().function.equals("cage")||block().name.startsWith("sack")||block().name.contains("present")||block().name.equals("lunch_basket");}
    public ItemStack packed(){unpackLootTable(null);var result=new ItemStack(block());if(block().function.equals("statue")&&hasCustomName())result.set(DataComponents.CUSTOM_NAME,getCustomName());if(block().function.equals("globe")){if(hasCustomName())result.set(DataComponents.CUSTOM_NAME,getCustomName());var tag=new net.minecraft.nbt.CompoundTag();tag.putBoolean("GlobeSheared",globeSheared);if(globePixels.length==512){tag.putByteArray("GlobePixels",globePixels);tag.putInt("GlobeSeason",globeSeason);}result.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));}if(block().function.equals("flag")){result.set(DataComponents.BANNER_PATTERNS,flagPatterns);if(hasCustomName())result.set(DataComponents.CUSTOM_NAME,getCustomName());}result.set(DataComponents.CONTAINER,net.minecraft.world.item.component.ItemContainerContents.fromItems(items));var liquid=io.github.jimbozoomer.jugcraft.fluid.StoredFluid.of(fluid);if(liquid!=null)result.set(io.github.jimbozoomer.jugcraft.fluid.JugcraftFluids.STORED_FLUID,liquid);OwnerSupplementVessel.occupant(result,captive);if(block().function.equals("spikes")&&spikeCharges>0){result.set(DataComponents.POTION_CONTENTS,spikePotion);var tag=result.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();tag.putInt("SpikeCharges",spikeCharges);result.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));}if(block().function.equals("blackboard")){var t=result.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();t.putByteArray("JugcraftBlackboard",boardPixels);t.putBoolean("BoardGlow",boardGlow);t.putBoolean("BoardWaxed",boardWaxed);result.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(t));}if(softPortions>0){var t=result.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();t.store("SoftDrink",ItemStack.CODEC,softDrink);t.putInt("SoftPortions",softPortions);result.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(t));}return result;}
    public void restore(ItemStack stack){if(block().function.equals("statue"))setCustomName(stack.get(DataComponents.CUSTOM_NAME));var soft=stack.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();softDrink=soft.read("SoftDrink",ItemStack.CODEC).orElse(ItemStack.EMPTY);softPortions=Math.clamp(soft.getIntOr("SoftPortions",0),0,OwnerSoftLiquids.capacity(this,softDrink));if(OwnerSoftLiquids.empty(softDrink).isEmpty())softPortions=0;if(softPortions==0)softDrink=ItemStack.EMPTY;if(block().function.equals("globe")){globePixels=soft.getByteArray("GlobePixels").filter(a->a.length==512).orElse(new byte[0]);globeSeason=soft.getIntOr("GlobeSeason",-1);if(stack.has(DataComponents.CUSTOM_NAME))setCustomName(stack.get(DataComponents.CUSTOM_NAME));globeSheared=stack.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getBooleanOr("GlobeSheared",false);}if(block().function.equals("flag")){flagPatterns=OwnerSupplementFlags.bounded(stack.getOrDefault(DataComponents.BANNER_PATTERNS,net.minecraft.world.level.block.entity.BannerPatternLayers.EMPTY));if(stack.has(DataComponents.CUSTOM_NAME))setCustomName(stack.get(DataComponents.CUSTOM_NAME));}if(block().function.equals("spikes")){spikePotion=stack.getOrDefault(DataComponents.POTION_CONTENTS,net.minecraft.world.item.alchemy.PotionContents.EMPTY);spikeCharges=Math.clamp(stack.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getIntOr("SpikeCharges",0),0,16);if(!spikePotion.hasEffects())spikeCharges=0;}if(block().function.equals("blackboard")){var t=stack.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag();boardPixels=OwnerBlackboards.pixels(t.getByteArray("JugcraftBlackboard").orElse(new byte[256]));boardGlow=t.getBooleanOr("BoardGlow",false);boardWaxed=t.getBooleanOr("BoardWaxed",false);}stack.getOrDefault(DataComponents.CONTAINER,net.minecraft.world.item.component.ItemContainerContents.EMPTY).copyInto(items);captive=OwnerSupplementVessel.occupant(stack);var liquid=stack.get(io.github.jimbozoomer.jugcraft.fluid.JugcraftFluids.STORED_FLUID);if(liquid!=null)liquid.restore(fluid);OwnerSoftLiquids.normalize(this);changed();}
    @Override public void preRemoveSideEffects(BlockPos p,BlockState s){if(!portable())super.preRemoveSideEffects(p,s);}
    public boolean mayEdit(Player p){return Menagerie.mayChange(level,p,worldPosition)&&(!block().function.equals("safe")||owner==null||owner.equals(p.getUUID())||keyPassword!=null&&OwnerKeyLocks.hasKey(p,keyPassword));}
    public boolean allowed(Player p){return mayEdit(p)||block().function.equals("notice")&&io.github.jimbozoomer.jugcraft.town.TownProtection.allowsPublicUse(p,level,worldPosition);}
    @Override public int getContainerSize(){return Math.max(1,block().capacity);}
    @Override protected NonNullList<ItemStack> getItems(){return items;}
    @Override protected void setItems(NonNullList<ItemStack> value){items=value;}
    @Override protected Component getDefaultName(){return Component.translatable(getBlockState().getBlock().getDescriptionId());}
    @Override protected AbstractContainerMenu createMenu(int id,Inventory inventory){return block().function.equals("cannon")?new OwnerCannonMenu(id,inventory,this):new OwnerSupplementMenu(id,inventory,this,block().function.equals("notice"));}
    @Override public boolean stillValid(Player p){return super.stillValid(p)&&allowed(p);}
    @Override public boolean canPlaceItem(int slot,ItemStack stack){
        if(softPortions>0||slot<0||slot>=block().capacity||!stack.getItem().canFitInsideContainerItems())return false;
        return switch(block().function){
            case "pulley"->OwnerPulleys.winding(stack);
            case "cannon"->slot==0?stack.is(Items.GUNPOWDER):OwnerCannon.rider(this)==null&&OwnerCannon.ammunition(stack);
            case "goblet"->false;
            case "hidden_bricks","spikes","rope_bunting","globe","way_sign","mob_head"->false;
            case "doormat"->true;
            case "books"->OwnerSupplementBooks.type(stack)!=null;
            case "jar"->captive==null&&fluid.isResourceBlank()&&(stack.is(Items.COOKIE)||stack.is(TagKey.create(Registries.ITEM,io.github.jimbozoomer.jugcraft.Jugcraft.id("supps_cookies"))));
            case "frame"->stack.getItem() instanceof BlockItem b&&!(b.getBlock() instanceof EntityBlock)&&b.getBlock().defaultBlockState().isCollisionShapeFullBlock(level,worldPosition);
            case "flowers"->stack.getItem() instanceof BlockItem b&&b.getBlock() instanceof VegetationBlock&&!(b.getBlock() instanceof DoublePlantBlock);
            case "lunch"->stack.has(DataComponents.FOOD);
            case "hourglass"->duration(stack)>0;
            case "notice"->stack.has(DataComponents.WRITTEN_BOOK_CONTENT)||stack.has(DataComponents.WRITABLE_BOOK_CONTENT)||stack.is(Items.FILLED_MAP);
            default->true;
        };
    }
    @Override public int getMaxStackSize(){return block().function.equals("goblet")||block().function.equals("statue")||block().function.equals("doormat")||block().function.equals("books")||block().function.equals("jar")||block().function.equals("frame")||block().function.equals("flowers")||block().function.equals("display")||block().function.equals("notice")||block().function.equals("hourglass")?1:64;}
    @Override public int[] getSlotsForFace(Direction direction){if(block().function.equals("mob_head")||block().function.equals("hidden_bricks"))return new int[0];if(block().function.equals("cannon"))return new int[]{direction==Direction.DOWN?0:1};return block().function.equals("way_sign")||block().function.equals("globe")||block().function.equals("rope_bunting")||block().function.equals("safe")||block().function.equals("notice")||block().function.equals("spikes")||block().function.equals("doormat")||block().function.equals("goblet")?new int[0]:java.util.stream.IntStream.range(0,block().capacity).toArray();}
    @Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction dir){return !block().function.equals("safe")&&(!block().function.equals("hourglass")||dir==Direction.UP&&getItem(0).isEmpty())&&canPlaceItem(slot,stack);}
    @Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction dir){return !block().function.equals("hidden_bricks")&&!block().function.equals("safe")&&!block().function.equals("notice")&&(!block().function.equals("hourglass")||(HouseholdBlock.value(getBlockState(),"facing").equals("up")?progress>=1:progress<=0));}
    @Override public void startOpen(ContainerUser user){if(!user.getLivingEntity().isSpectator()){viewers++;opened();}}
    @Override public void stopOpen(ContainerUser user){if(!user.getLivingEntity().isSpectator()){viewers=Math.max(0,viewers-1);opened();}}
    private void opened(){if(level!=null&&!level.isClientSide()){level.setBlockAndUpdate(worldPosition,HouseholdBlock.set(getBlockState(),"open",Boolean.toString(viewers>0)));level.updateNeighborsAt(worldPosition,block());}}
    public void changed(){setChanged();if(level!=null&&block().function.equals("pulley")){var next=HouseholdBlock.set(getBlockState(),"winding",OwnerPulleys.windingName(getItem(0)));if(next!=getBlockState())level.setBlockAndUpdate(worldPosition,next);}if(level!=null){if(block().function.equals("statue")){var next=HouseholdBlock.set(getBlockState(),"lit",Boolean.toString(getItem(0).is(net.minecraft.tags.ItemTags.CANDLES)));if(next!=getBlockState())level.setBlockAndUpdate(worldPosition,next);}if(block().function.equals("books")){int count=0;for(var stack:items)if(!stack.isEmpty())count++;var next=HouseholdBlock.set(getBlockState(),"books",Integer.toString(Math.max(1,count)));if(next!=getBlockState())level.setBlockAndUpdate(worldPosition,next);}if(block().function.equals("spikes")){var next=HouseholdBlock.set(getBlockState(),"tipped",Boolean.toString(spikeCharges>0));if(next!=getBlockState())level.setBlockAndUpdate(worldPosition,next);}if(block().function.equals("hourglass")){var data=sandData(getItem(0));var next=HouseholdBlock.set(getBlockState(),"light_level",Integer.toString(data!=null&&data.has("light_level")?data.get("light_level").getAsInt():0));if(next!=getBlockState())level.setBlockAndUpdate(worldPosition,next);}var s=HouseholdBlock.set(getBlockState(),"has_book",Boolean.toString(!getItem(0).isEmpty()));if(s!=getBlockState())level.setBlockAndUpdate(worldPosition,s);level.sendBlockUpdated(worldPosition,s,s,Block.UPDATE_CLIENTS);level.updateNeighbourForOutputSignal(worldPosition,block());}}
    @Override public void setItem(int slot,ItemStack stack){super.setItem(slot,stack);if(block().function.equals("hourglass")){progress=HouseholdBlock.value(getBlockState(),"facing").equals("down")?1:0;power=stack.isEmpty()?0:1;}changed();}
    public void tick(ServerLevel server){
        if(block().function.equals("statue")&&server.getGameTime()>=nextHolidayCheck){
            nextHolidayCheck=server.getGameTime()+200;
            var date=io.github.jimbozoomer.jugcraft.season.JugcraftSeasons.settings().effectiveDate(io.github.jimbozoomer.jugcraft.season.JugcraftSeasons.date());
            int holiday=date.getMonthValue()==10&&date.getDayOfMonth()==31?1:date.getMonthValue()==12&&date.getDayOfMonth()>=24&&date.getDayOfMonth()<=26||date.getMonthValue()==4&&date.getDayOfMonth()==1?2:0;
            if(statueHoliday!=holiday){statueHoliday=holiday;changed();}
        }
        String kind=block().function;if(kind.equals("way_sign"))OwnerRoadSigns.tick(server,this);if(kind.equals("slidy"))OwnerSlidingBlocks.tick(server,this);if(kind.equals("fuse"))OwnerGunpowder.tick(server,this);if(kind.equals("bubble"))OwnerBubbles.tick(server,this);if(kind.equals("mob_head"))OwnerMobHeads.tick(server,this);if(kind.equals("cannon"))OwnerCannon.tick(server,this);if(kind.equals("globe"))OwnerGlobes.tick(server,this);if(kind.equals("statue")){var next=HouseholdBlock.set(getBlockState(),"powered",Boolean.toString(server.hasNeighborSignal(worldPosition)));if(next!=getBlockState())server.setBlockAndUpdate(worldPosition,next);}if(kind.equals("speaker"))OwnerSupplementText.tick(server,this);if(kind.equals("bellows"))OwnerSupplementAir.tick(server,this);if(kind.startsWith("spring"))OwnerSupplementSprings.tick(server,this);
        if(kind.equals("relayer")){var facing=HouseholdBlock.facing(getBlockState());var source=worldPosition.relative(facing);int input=server.getSignal(source,facing);var state=server.getBlockState(source);if(state.getBlock() instanceof RedstoneWireBlock)input=Math.max(input,state.getValue(RedstoneWireBlock.POWER));else if(server.getBlockEntity(source) instanceof OwnerSupplementData other&&other.block().function.equals("relayer"))input=Math.max(input,other.power);if(input!=power){power=Math.clamp(input,0,15);server.setBlockAndUpdate(worldPosition,HouseholdBlock.set(getBlockState(),"powered",Boolean.toString(power>0)));changed();server.updateNeighborsAt(worldPosition,block());server.updateNeighborsAt(worldPosition.relative(facing.getOpposite()),block());}}
        if(kind.equals("faucet")&&server.getGameTime()%20==0)OwnerSupplementTransfers.faucet(this,server);
        if(kind.equals("wind")&&server.getGameTime()%20==0){int next=server.getGameTime()<pulseUntil?3:server.isThundering()?2:server.isRaining()?1:0;if(next!=power){power=next;changed();server.updateNeighborsAt(worldPosition,block());server.updateNeighborsAt(worldPosition.below(),block());}}
        else if((kind.equals("redstone_display")||kind.equals("illuminator"))&&server.getGameTime()%4==0){int signal=server.getBestNeighborSignal(worldPosition);var next=HouseholdBlock.set(getBlockState(),"power",Integer.toString(signal));if(next!=getBlockState())server.setBlockAndUpdate(worldPosition,next);}
        else if(kind.equals("hourglass")){
            int duration=duration(getItem(0));boolean down=HouseholdBlock.value(getBlockState(),"facing").equals("down"),up=HouseholdBlock.value(getBlockState(),"facing").equals("up");
            if(duration>0&&(down||up)){progress=Math.clamp(progress+(down?-1F:1F)/duration,0,1);int next=1+(int)((down?1-progress:progress)*14);if(next!=power){power=next;changed();}}
        }else if(kind.equals("clock")&&server.getGameTime()%20==0){int next=(int)(Math.floorMod(server.getDefaultClockTime()+6000,24000)*15/24000);if(next!=power){power=next;changed();}long hour=(server.getDefaultClockTime()+6000)/1000;if(hour!=lastClock){if(lastClock>=0)server.playSound(null,worldPosition,net.minecraft.sounds.SoundEvents.NOTE_BLOCK_BELL.value(),net.minecraft.sounds.SoundSource.BLOCKS,.3F,1);lastClock=hour;}}
        
        else if(kind.equals("rope_bunting"))OwnerBuntings.tick(server,this);
        else if(kind.equals("turntable"))OwnerSupplementRotation.tick(server,this);
        if(server.getGameTime()%20==0&&viewers>0){int count=0;for(var p:server.players())if(p.containerMenu instanceof OwnerSupplementMenu m&&m.source==this)count++;if(count!=viewers){viewers=count;opened();}}
    }
    void rotate(ServerLevel server){
        var actor=Authority.present(server,owner);var direction=HouseholdBlock.facing(getBlockState());
        if(actor!=null&&Authority.mayChange(server,actor,worldPosition)&&OwnerSupplementRotation.rotate(server,actor,worldPosition.relative(direction),direction,HouseholdBlock.flag(getBlockState(),"inverted"))){pulseUntil=server.getGameTime()+4;changed();}
    }
    private static boolean matches(JsonElement refs,ItemStack stack){
        if(refs.isJsonArray()){for(var v:refs.getAsJsonArray())if(matches(v,stack))return true;return false;}
        String id=refs.getAsString();return id.startsWith("#")?stack.is(TagKey.create(Registries.ITEM,Identifier.parse(id.substring(1)))):net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString().equals(Identifier.parse(id).toString());
    }
    public static JsonObject sandData(ItemStack stack){
        if(stack.isEmpty()||OwnerSupplementaries.HOURGLASS==null)return null;JsonObject selected=null;int order=Integer.MAX_VALUE;
        for(var v:OwnerSupplementaries.HOURGLASS){var d=v.getAsJsonObject();int priority=d.has("ordering")?d.get("ordering").getAsInt():0;if(priority<order&&matches(d.get("items"),stack)){order=priority;selected=d;}}
        return selected;
    }
    public static int duration(ItemStack stack){var value=sandData(stack);return value==null?0:value.get("duration").getAsInt();}
    @Override protected void saveAdditional(ValueOutput out){super.saveAdditional(out);out.putInt("StatueHoliday",statueHoliday);out.store("SoftDrink",ItemStack.OPTIONAL_CODEC,softDrink);out.putInt("SoftPortions",softPortions);out.putBoolean("AntiqueText",antiqueText);if(slideActor!=null)out.store("SlideActor",UUIDUtil.CODEC,slideActor);if(slideDirection!=null)out.putString("SlideDirection",slideDirection.getName());if(fuseActor!=null)out.store("FuseActor",UUIDUtil.CODEC,fuseActor);if(block().function.equals("bubble"))out.putInt("BubbleAge",bubbleAge);if(keyPassword!=null)out.putString("KeyPassword",keyPassword);if(OwnerMobHeads.head(this))out.putInt("HeadWatch",headWatch);if(block().function.equals("cannon")){if(cannonPearl!=null)out.store("CannonPearl",UUIDUtil.CODEC,cannonPearl);out.putInt("CannonPower",cannonPower);out.putFloat("CannonYaw",cannonYaw);out.putFloat("CannonPitch",cannonPitch);out.putInt("CannonFuse",cannonFuse);out.putInt("CannonCooldown",cannonCooldown);out.putBoolean("CannonPowered",cannonPowered);if(cannonActor!=null)out.store("CannonActor",UUIDUtil.CODEC,cannonActor);}if(OwnerWaySigns.sign(this)){out.putBoolean("RoadPending",roadPending);out.store("WayBase",BlockState.CODEC,wayBase);for(int i=0;i<2;i++){out.putString("WayText"+i,wayTexts[i]);out.putInt("WayAngle"+i,wayAngles[i]);}}if(block().function.equals("globe")){out.store("GlobePixels",com.mojang.serialization.Codec.BYTE_BUFFER,java.nio.ByteBuffer.wrap(globePixels));out.putInt("GlobeSeason",globeSeason);out.putFloat("GlobeSpin",globeSpin);out.putBoolean("GlobeSheared",globeSheared);}if(block().function.equals("flag"))out.store("FlagPatterns",net.minecraft.world.level.block.entity.BannerPatternLayers.CODEC,flagPatterns);if(block().function.equals("spikes")){out.store("SpikePotion",net.minecraft.world.item.alchemy.PotionContents.CODEC,spikePotion);out.putInt("SpikeCharges",spikeCharges);out.putLong("SpikeLastHit",spikeLastHit);}if(OwnerSupplementText.text(this)){out.putString("Message",message);out.putInt("TextMode",textMode);out.putInt("TextRange",textRange);out.putInt("TextColor",textColor);}if(block().function.equals("blackboard")||OwnerSupplementText.text(this)){out.store("BoardPixels",com.mojang.serialization.Codec.BYTE_BUFFER,java.nio.ByteBuffer.wrap(boardPixels));out.putBoolean("BoardGlow",boardGlow);out.putBoolean("BoardWaxed",boardWaxed);out.putLong("BoardRevision",boardRevision);}fluid.writeValue(out);if(captive!=null)out.store("Captive",net.minecraft.nbt.CompoundTag.CODEC,captive);if(!trySaveLootTable(out))ContainerHelper.saveAllItems(out,items);if(owner!=null)out.store("Owner",UUIDUtil.CODEC,owner);out.putFloat("Progress",progress);out.putInt("Power",power);out.putLong("PulseUntil",pulseUntil);}
    @Override protected void loadAdditional(ValueInput in){super.loadAdditional(in);statueHoliday=Math.clamp(in.getIntOr("StatueHoliday",0),0,2);softDrink=in.read("SoftDrink",ItemStack.OPTIONAL_CODEC).orElse(ItemStack.EMPTY);softPortions=Math.clamp(in.getIntOr("SoftPortions",0),0,OwnerSoftLiquids.capacity(this,softDrink));if(OwnerSoftLiquids.empty(softDrink).isEmpty())softPortions=0;if(softPortions==0)softDrink=ItemStack.EMPTY;antiqueText=in.getBooleanOr("AntiqueText",false);slideActor=in.read("SlideActor",UUIDUtil.CODEC).orElse(null);slideDirection=Direction.byName(in.getStringOr("SlideDirection",""));fuseActor=in.read("FuseActor",UUIDUtil.CODEC).orElse(null);bubbleAge=Math.clamp(in.getIntOr("BubbleAge",0),0,100000);keyPassword=in.getString("KeyPassword").orElse(null);if(keyPassword!=null&&keyPassword.length()>256)keyPassword=keyPassword.substring(0,256);headWatch=Math.clamp(in.getIntOr("HeadWatch",0),0,225);cannonPearl=in.read("CannonPearl",UUIDUtil.CODEC).orElse(null);cannonPower=Math.clamp(in.getIntOr("CannonPower",1),1,4);cannonYaw=in.getFloatOr("CannonYaw",0);if(!Float.isFinite(cannonYaw))cannonYaw=0;cannonYaw=net.minecraft.util.Mth.wrapDegrees(cannonYaw);cannonPitch=in.getFloatOr("CannonPitch",-10);if(!Float.isFinite(cannonPitch))cannonPitch=-10;cannonPitch=Math.clamp(cannonPitch,-90,90);cannonFuse=Math.clamp(in.getIntOr("CannonFuse",0),0,OwnerCannon.FUSE);cannonCooldown=Math.clamp(in.getIntOr("CannonCooldown",0),0,OwnerCannon.COOLDOWN);cannonPowered=in.getBooleanOr("CannonPowered",false);cannonActor=in.read("CannonActor",UUIDUtil.CODEC).orElse(null);roadPending=in.getBooleanOr("RoadPending",false);wayBase=in.read("WayBase",BlockState.CODEC).filter(OwnerWaySigns::base).orElse(Blocks.AIR.defaultBlockState());for(int i=0;i<2;i++){wayTexts[i]=OwnerSupplementText.clean(in.getStringOr("WayText"+i,"")).replace("\n"," ");if(wayTexts[i].length()>75)wayTexts[i]=wayTexts[i].substring(0,75);wayAngles[i]=Math.floorMod(in.getIntOr("WayAngle"+i,0),16);}globePixels=in.read("GlobePixels",com.mojang.serialization.Codec.BYTE_BUFFER).filter(b->b.remaining()==512).map(b->{byte[] a=new byte[512];b.get(a);return a;}).orElse(new byte[0]);globeSeason=in.getIntOr("GlobeSeason",-1);globeSpin=Math.clamp(in.getFloatOr("GlobeSpin",0),0,9000);if(!Float.isFinite(globeSpin))globeSpin=0;globeSheared=in.getBooleanOr("GlobeSheared",false);flagPatterns=OwnerSupplementFlags.bounded(in.read("FlagPatterns",net.minecraft.world.level.block.entity.BannerPatternLayers.CODEC).orElse(net.minecraft.world.level.block.entity.BannerPatternLayers.EMPTY));message=OwnerSupplementText.clean(in.getStringOr("Message",""));textMode=Math.clamp(in.getIntOr("TextMode",0),0,3);textRange=Math.clamp(in.getIntOr("TextRange",16),4,64);textColor=in.getIntOr("TextColor",0xFFF0E6CE);spikePotion=in.read("SpikePotion",net.minecraft.world.item.alchemy.PotionContents.CODEC).orElse(net.minecraft.world.item.alchemy.PotionContents.EMPTY);spikeCharges=spikePotion.hasEffects()?Math.clamp(in.getIntOr("SpikeCharges",0),0,16):0;spikeLastHit=in.getLongOr("SpikeLastHit",Long.MIN_VALUE/2);boardPixels=in.read("BoardPixels",com.mojang.serialization.Codec.BYTE_BUFFER).filter(b->b.remaining()==256).map(b->{byte[] v=new byte[256];b.get(v);return OwnerBlackboards.pixels(v);}).orElse(new byte[256]);boardGlow=in.getBooleanOr("BoardGlow",false);boardWaxed=in.getBooleanOr("BoardWaxed",false);boardRevision=in.getLongOr("BoardRevision",0);captive=in.read("Captive",net.minecraft.nbt.CompoundTag.CODEC).orElse(null);snapshotTick=in.getLongOr("SnapshotTick",0);items=NonNullList.withSize(getContainerSize(),ItemStack.EMPTY);if(!tryLoadLootTable(in))ContainerHelper.loadAllItems(in,items);fluid.readValue(in);OwnerSoftLiquids.normalize(this);owner=in.read("Owner",UUIDUtil.CODEC).orElse(null);progress=Math.clamp(in.getFloatOr("Progress",0),0,1);power=Math.clamp(in.getIntOr("Power",0),0,15);pulseUntil=in.getLongOr("PulseUntil",0);}
    @Override public net.minecraft.nbt.CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=saveWithoutMetadata(lookup);if(!Set.of("display","notice","hourglass","flowers","frame","jar","cage","books","statue","goblet","way_sign","cannon").contains(block().function)){tag.remove("Items");tag.remove("LootTable");tag.remove("LootTableSeed");}tag.remove("KeyPassword");tag.remove("FuseActor");tag.remove("SlideActor");tag.remove("Owner");tag.remove("CannonActor");tag.remove("CannonPearl");if(level!=null)tag.putLong("SnapshotTick",level.getGameTime());return tag;}
    @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
